{
  "name": "akm-opencode",
  "version": "0.10.261121",
  "type": "module",
  "description": "OpenCode plugin for AKM with discovery tools, feedback, memory, and automatic learning proposals from corrections and recurring workflows.",
  "keywords": [
    "opencode",
    "opencode-ai",
    "opencode-plugin",
    "opencode-extensions",
    "akm",
    "ai-agent",
    "developer-tools",
    "plugin"
  ],
  "homepage": "https://github.com/itlackey/akm-plugins#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/itlackey/akm-plugins.git",
    "directory": "opencode"
  },
  "bugs": {
    "url": "https://github.com/itlackey/akm-plugins/issues"
  },
  "license": "MPL-2.0",
  "files": [
    "dist/",
    "README.md"
  ],
  "main": "./dist/index.js",
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "build": "bun build ./index.ts --target=bun --outfile=dist/index.js --external @opencode-ai/plugin --external akm-cli",
    "prepack": "bun run build",
    "typecheck": "tsc -p tsconfig.json"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.18.14",
    "akm-cli": "0.10.261119"
  },
  "devDependencies": {
    "@types/node": "^26.1.1",
    "typescript": "^5.8.3"
  }
}
